import { readTestId } from '../dom/addressing/testid-attr.js';
import { EventType } from '@reticlehq/core';
import { getAccessibleName, isSensitiveField } from '../dom/a11y.js';
const MAX_VALUE_LEN = 160;
const BURST_MS = 150;
function isField(target) {
    return (target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        target instanceof HTMLSelectElement);
}
function fieldName(element) {
    const testid = readTestId(element);
    if (null !== testid && testid.length > 0)
        return testid;
    if (element.name.length > 0)
        return element.name;
    const accessible = getAccessibleName(element);
    if (accessible.length > 0)
        return accessible;
    const id = element.getAttribute('id');
    return null !== id && id.length > 0 ? id : element.tagName.toLowerCase();
}
export function installField(emit) {
    const ac = new AbortController();
    const { signal } = ac;
    const pending = new Map();
    const report = (element, kind) => {
        const value = element.value;
        const secret = isSensitiveField(element);
        emit(EventType.FIELD_CHANGE, {
            field: fieldName(element),
            kind,
            length: value.length,
            ...(secret
                ? { redacted: true }
                : { value: value.length > MAX_VALUE_LEN ? `${value.slice(0, MAX_VALUE_LEN)}…` : value }),
        });
    };
    const clear = (element) => {
        const timer = pending.get(element);
        if (timer !== undefined)
            clearTimeout(timer);
        pending.delete(element);
    };
    const onInput = (event) => {
        const element = event.target;
        if (!isField(element))
            return;
        clear(element);
        pending.set(element, setTimeout(() => {
            pending.delete(element);
            report(element, 'input');
        }, BURST_MS));
    };
    const onChange = (event) => {
        const element = event.target;
        if (!isField(element))
            return;
        clear(element);
        report(element, 'change');
    };
    document.addEventListener('input', onInput, { signal, capture: true });
    document.addEventListener('change', onChange, { signal, capture: true });
    return () => {
        for (const timer of pending.values())
            clearTimeout(timer);
        pending.clear();
        ac.abort();
    };
}
