const PINIA_SUBSCRIBE_OPTIONS = { detached: true, flush: 'sync' };
export function piniaStore(store) {
    return {
        getState: () => snapshotLive(store.$state),
        subscribe: (listener) => store.$subscribe(() => listener(), { ...PINIA_SUBSCRIBE_OPTIONS }),
    };
}
export function pushStore(initial) {
    let current = initial;
    const listeners = new Set();
    const subscribe = (listener) => {
        listeners.add(listener);
        return () => listeners.delete(listener);
    };
    return {
        store: { getState: () => current, subscribe },
        push: (value) => {
            current = value;
            for (const listener of listeners)
                listener();
        },
    };
}
