import { fnv1a } from '@reticlehq/core';
export const REPEAT_BURST = 3;
export const MAX_TRACKED_FINGERPRINTS = 256;
const PASS = { emit: true };
const DROP = { emit: false };
function isCheckpoint(count) {
    if (count < 10)
        return false;
    let n = count;
    while (0 === n % 10)
        n /= 10;
    return 1 === n;
}
export function fingerprintError(identity) {
    return fnv1a([
        identity.message,
        identity.source ?? '',
        undefined === identity.line ? '' : String(identity.line),
        identity.kind ?? '',
        identity.stack ?? '',
    ].join('\x00'));
}
export function createRepeatLimiter(burst = REPEAT_BURST, maxTracked = MAX_TRACKED_FINGERPRINTS) {
    const counts = new Map();
    return {
        admit(identity) {
            const key = fingerprintError(identity);
            const seen = (counts.get(key) ?? 0) + 1;
            counts.delete(key);
            if (counts.size >= maxTracked) {
                const oldest = counts.keys().next();
                if (!(oldest.done ?? false))
                    counts.delete(oldest.value);
            }
            counts.set(key, seen);
            if (seen <= burst)
                return PASS;
            return isCheckpoint(seen) ? { emit: true, repeats: seen } : DROP;
        },
    };
}
