    command: 'metaKey',
    super: 'metaKey',
    win: 'metaKey',
    control: 'ctrlKey',
    ctrl: 'ctrlKey',
    shift: 'shiftKey',
    alt: 'altKey',
    option: 'altKey',
    opt: 'altKey',
