import { BlindSpotKind, EventType, REDACTED_VALUE } from '@reticlehq/core';
import { subscribableStores, onStoreRegistered, } from '../registry/stores.js';
import { isSensitiveKey, sanitizeForTransport } from '../security/serialization.js';
import { observeSafely } from './types.js';
function isRecord(value) {
    return 'object' === typeof value && value !== null && !Array.isArray(value);
}
export function diffState(prev, next) {
    if (!isRecord(prev) || !isRecord(next)) {
        return Object.is(prev, next) ? [] : [{ path: '', old: prev, new: next }];
    }
    const changes = [];
    for (const key of new Set([...Object.keys(prev), ...Object.keys(next)])) {
        if (!Object.is(prev[key], next[key]))
            changes.push({ path: key, old: prev[key], new: next[key] });
    }
    return changes;
}
function project(path, value) {
    return isSensitiveKey(path) ? REDACTED_VALUE : sanitizeForTransport(value);
}
function samePresentedValue(oldValue, newValue) {
    if (Object.is(oldValue, newValue))
        return true;
    try {
        return JSON.stringify(oldValue) === JSON.stringify(newValue);
    }
    catch {
        return false;
    }
}
function safeRead(getter) {
    try {
        return getter();
    }
    catch {
        return undefined;
    }
}
export function installStoreState(emit) {
    const active = new Map();
    const watch = ([name, getter, subscribe]) => {
        try {
            active.get(name)?.();
        }
        catch {
        }
        let last = safeRead(getter);
        active.set(name, subscribe(() => {
            observeSafely(() => {
                const next = safeRead(getter);
                const changes = diffState(last, next);
                last = next;
                for (const change of changes) {
                    const value = project(change.path, change.new);
                    const old = project(change.path, change.old);
                    const same = isSensitiveKey(change.path)
                        ? samePresentedValue(sanitizeForTransport(change.old), sanitizeForTransport(change.new))
                        : samePresentedValue(old, value);
                    if (same)
                        continue;
                    observeSafely(() => emit(EventType.STATE_CHANGE, { name, path: change.path, value, old }));
                }
            });
        }));
    };
    for (const entry of subscribableStores())
        watch(entry);
    if (0 === active.size) {
        emit(EventType.BLIND_SPOT, { kind: BlindSpotKind.UNWATCHED_STATE, count: 1 });
    }
    const offRegistered = onStoreRegistered((entry) => {
        const wasDark = 0 === active.size;
        watch(entry);
        if (wasDark && active.size > 0) {
            emit(EventType.BLIND_SPOT, { kind: BlindSpotKind.UNWATCHED_STATE, count: 0 });
        }
    });
    return () => {
        offRegistered();
        for (const unsubscribe of active.values()) {
            try {
                unsubscribe();
            }
            catch {
            }
        }
        active.clear();
    };
}
