import { ActionType } from '@reticlehq/core';
import { isInput } from '../dom/realm.js';
const ARIA_TOGGLE_ROLES = new Set(['checkbox', 'switch']);
const ARIA_CHECKED = 'aria-checked';
export const isAriaToggle = (el) => !isInput(el) && ARIA_TOGGLE_ROLES.has(el.getAttribute('role') ?? '');
export const ariaChecked = (el) => 'true' === el.getAttribute(ARIA_CHECKED);
export function assertAriaToggleLanded(el, action, skipped) {
    if (skipped || !isAriaToggle(el))
        return;
    if (action !== ActionType.CHECK && action !== ActionType.UNCHECK)
        return;
    const wanted = action === ActionType.CHECK;
    if (ariaChecked(el) === wanted)
        return;
    throw new Error(`${action} clicked the ${el.getAttribute('role') ?? ''} but ${ARIA_CHECKED} is still "${String(!wanted)}" — the app did not toggle it`);
}
export function alreadyAtCheckedState(el, action) {
    if (action !== ActionType.CHECK && action !== ActionType.UNCHECK)
        return false;
    const wanted = action === ActionType.CHECK;
    if (isInput(el))
        return el.checked === wanted;
    return isAriaToggle(el) && ariaChecked(el) === wanted;
}
