import { EventType, ScrollDirection } from '@reticlehq/core';
import { refs } from '../dom/addressing/refs.js';
import { nativeSetTimeout, nativeClearTimeout } from '../timers/native/native-timers.js';
const THROTTLE_MS = 100;
const REVEAL_SELECTOR = '[data-reticle-reveal], [data-reveal], section';
export function installScroll(emit) {
    const ac = new AbortController();
    const { signal } = ac;
    let lastEmit = 0;
    let lastY = 0;
    let trailingTimer;
    const emitPosition = () => {
        lastEmit = performance.now();
        const y = window.scrollY;
        const max = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
        emit(EventType.SCROLL_POSITION, {
            x: window.scrollX,
            y,
            percent: Math.round((y / max) * 100),
            direction: y >= lastY ? ScrollDirection.DOWN : ScrollDirection.UP,
        });
        lastY = y;
    };
    const onScroll = () => {
        const elapsed = performance.now() - lastEmit;
        if (elapsed >= THROTTLE_MS) {
            if (trailingTimer !== undefined) {
                nativeClearTimeout(trailingTimer);
                trailingTimer = undefined;
            }
            emitPosition();
            return;
        }
        if (trailingTimer === undefined) {
            trailingTimer = nativeSetTimeout(() => {
                trailingTimer = undefined;
                emitPosition();
            }, THROTTLE_MS - elapsed);
        }
    };
    window.addEventListener('scroll', onScroll, { passive: true, signal });
    let io;
    if ('function' === typeof IntersectionObserver) {
        io = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                if (entry.isIntersecting) {
                    emit(EventType.REVEAL_SHOWN, { ratio: entry.intersectionRatio }, refs.refFor(entry.target));
                }
            }
        }, { threshold: 0.25 });
        const observer = io;
        for (const el of document.querySelectorAll(REVEAL_SELECTOR))
            observer.observe(el);
    }
    return () => {
        ac.abort();
        if (trailingTimer !== undefined)
            nativeClearTimeout(trailingTimer);
        io?.disconnect();
    };
}
