const UNMOUNTED_RATIO = 0.25;
const MIN_SCROLL_RATIO = 1.2;
function rowHost(container) {
    let host = container;
    for (let depth = 0; depth < 3; depth += 1) {
        const children = Array.from(host.children).filter((c) => c instanceof HTMLElement);
        const only = 1 === children.length ? children[0] : undefined;
        if (only === undefined)
            return host;
        if (only.offsetHeight < host.scrollHeight * 0.9)
            return host;
        host = only;
    }
    return host;
}
export function unmountedRowsIn(container) {
    const scrollHeight = container.scrollHeight;
    const clientHeight = container.clientHeight;
    if (clientHeight <= 0 || scrollHeight < clientHeight * MIN_SCROLL_RATIO)
        return 0;
    const host = rowHost(container);
    const rows = Array.from(host.children).filter((c) => c instanceof HTMLElement);
    if (rows.length < 2)
        return 0;
    let top = Infinity;
    let bottom = 0;
    let totalHeight = 0;
    for (const row of rows) {
        const rowTop = row.offsetTop;
        const rowBottom = rowTop + row.offsetHeight;
        if (rowTop < top)
            top = rowTop;
        if (rowBottom > bottom)
            bottom = rowBottom;
        totalHeight += row.offsetHeight;
    }
    const empty = Math.max(0, top) + Math.max(0, scrollHeight - bottom);
    if (empty < scrollHeight * UNMOUNTED_RATIO)
        return 0;
    const averageRow = totalHeight / rows.length;
    if (averageRow <= 0)
        return 0;
    return Math.round(empty / averageRow);
}
export function countUnmountedRows() {
    let total = 0;
    for (const element of document.querySelectorAll('*')) {
        if (element.scrollHeight <= element.clientHeight)
            continue;
        total += unmountedRowsIn(element);
    }
    return total;
}
