import { registerCapabilities } from './capabilities.js';
export function registerReticleDomain(domain) {
    const input = {};
    if (domain.testids !== undefined)
        input.testids = [...domain.testids];
    if (domain.signals !== undefined)
        input.signals = [...domain.signals];
    if (domain.stores !== undefined)
        input.stores = [...domain.stores];
    registerCapabilities(input);
}
