import { CoverageMarker, SOURCE_MAPPING_CAPABILITY, DATA_RETICLE_SOURCE_ATTR, RETICLE_OVERLAY_SELECTOR, } from '@reticlehq/core';
import { testIdSelector } from './testid-attr.js';
const appCarries = (doc, selector) => Array.from(doc.querySelectorAll(selector)).some((el) => null === el.closest(RETICLE_OVERLAY_SELECTOR));
export function coverageMarkers(doc) {
    return [
        ...(appCarries(doc, `[${DATA_RETICLE_SOURCE_ATTR}]`) ? [CoverageMarker.SOURCE] : []),
        ...(appCarries(doc, testIdSelector()) ? [CoverageMarker.TESTID] : []),
    ];
}
export function notApplicableFor(page) {
    const couldStamp = page.buildPlugin || 0 < page.adapters.length || page.markers.includes(CoverageMarker.SOURCE);
    return couldStamp ? [] : [SOURCE_MAPPING_CAPABILITY];
}
