import { EventType, StreamDirection, StreamTransport } from '@reticlehq/core';
import { isStreamingBody } from './net-detail/network-body.js';
import { nativeClearTimeout, nativeSetTimeout } from '../timers/native/native-timers.js';
const STREAM_WATCH_MS = 10_000;
export function watchStreamedBody(emit, res, id, urlFields, contentType, contentLength) {
    if (!isStreamingBody(contentType, contentLength))
        return;
    if (typeof res.body?.getReader !== 'function')
        return;
    let clone;
    try {
        clone = res.clone();
    }
    catch {
        return;
    }
    const body = clone.body;
    if (null === body)
        return;
    emit(EventType.NET_STREAM, {
        transport: StreamTransport.FETCH,
        direction: StreamDirection.OPEN,
        ...urlFields,
        id,
    });
    void (async () => {
        const reader = body.getReader();
        let gaveUp = false;
        let timer;
        const expired = new Promise((resolve) => {
            timer = nativeSetTimeout(() => resolve('expired'), STREAM_WATCH_MS);
        });
        try {
            for (;;) {
                const next = await Promise.race([reader.read(), expired]);
                if ('expired' === next) {
                    gaveUp = true;
                    void reader.cancel().catch(() => undefined);
                    break;
                }
                if (next.done)
                    break;
            }
        }
        catch {
        }
        finally {
            if (timer !== undefined)
                nativeClearTimeout(timer);
        }
        emit(EventType.NET_STREAM, {
            transport: StreamTransport.FETCH,
            direction: StreamDirection.CLOSE,
            ...urlFields,
            id,
            ...(gaveUp ? { gaveUp: true } : {}),
        });
    })();
}
