import { isReticleUi } from './dom-ignore.js';
const SAMPLE_POINTS = [
    [0.5, 0.5],
    [0.25, 0.25],
    [0.75, 0.25],
    [0.25, 0.75],
    [0.75, 0.75],
];
const BLOCKED_MAJORITY = 3;
export function hitTestOccluder(el, rect) {
    if (0 === rect.width || 0 === rect.height)
        return null;
    const doc = el.ownerDocument;
    if (typeof doc.elementFromPoint !== 'function')
        return null;
    const withStack = doc;
    const isOursButNotTheTarget = (candidate) => isReticleUi(candidate) &&
        candidate !== el &&
        !el.contains(candidate) &&
        !candidate.contains(el);
    const topAt = (x, y) => {
        const found = withStack.elementsFromPoint?.(x, y) ?? [doc.elementFromPoint(x, y)];
        return found.find((c) => null !== c && !isOursButNotTheTarget(c)) ?? null;
    };
    const blockers = new Map();
    for (const [fx, fy] of SAMPLE_POINTS) {
        const top = topAt(rect.left + rect.width * fx, rect.top + rect.height * fy);
        if (null === top)
            continue;
        if (top === el || el.contains(top) || top.contains(el))
            continue;
        blockers.set(top, (blockers.get(top) ?? 0) + 1);
    }
    let worst = null;
    let worstCount = 0;
    for (const [element, count] of blockers) {
        if (count > worstCount) {
            worst = element;
            worstCount = count;
        }
    }
    return worstCount >= BLOCKED_MAJORITY ? worst : null;
}
